#include <stdio.h>

static unsigned long long power(unsigned long long base, unsigned int exponent)
{
    unsigned long long result = 1;
    while (exponent > 0) {
        if (exponent % 2 == 1) { result *= base; }
        exponent /= 2;
        if (exponent > 0) { base *= base; }
    }
    return result;
}

int main(void)
{
    printf("%llu\n",power(3,5));
    return 0;
}

#include <stdio.h>

static unsigned long long modular_power(unsigned long long base, unsigned int exponent,
                                        unsigned long long modulus)
{
    unsigned long long result = 1 % modulus;
    base %= modulus;
    while (exponent > 0) {
        if (exponent % 2 == 1) { result = result * base % modulus; }
        base = base * base % modulus;
        exponent /= 2;
    }
    return result;
}

int main(void)
{
    printf("%llu\n",modular_power(3,13,13));
    return 0;
}

